48	/**
49	 * Buffered {@link FileWriter} that supports atomic operations.
50	 *
51	 * <p>
52	 * The write operation is atomic when used for overwriting;
53	 * it either leaves the original file intact, or it completely rewrites it with new contents.
54	 *
55	 * @author Kohsuke Kawaguchi
56	 */
57	public class AtomicFileWriter extends Writer {
58	
59	    private static final Logger LOGGER = Logger.getLogger(AtomicFileWriter.class.getName());
60	
61	    private static final Cleaner CLEANER = Cleaner.create(
62	            new NamingThreadFactory(new DaemonThreadFactory(), AtomicFileWriter.class.getName() + ".cleaner"));
63	
64	    private static /* final */ boolean DISABLE_FORCED_FLUSH = SystemProperties.getBoolean(
65	            AtomicFileWriter.class.getName() + ".DISABLE_FORCED_FLUSH");
66	
67	    private static /* final */ boolean REQUIRES_DIR_FSYNC = SystemProperties.getBoolean(
68	            AtomicFileWriter.class.getName() + ".REQUIRES_DIR_FSYNC", !Functions.isWindows());
69	
70	    static {
71	        if (DISABLE_FORCED_FLUSH) {
72	            LOGGER.log(Level.WARNING, "DISABLE_FORCED_FLUSH flag used, this could result in dataloss if failures happen in your storage subsystem.");
73	        }
74	    }
75	
76	    private final FileChannelWriter core;
77	    private final Path tmpPath;
78	    private final Path destPath;
79	
80	    /**
81	     * Writes with UTF-8 encoding.
82	     */
83	    public AtomicFileWriter(File f) throws IOException {
84	        this(toPath(f), StandardCharsets.UTF_8);
85	    }
86	
87	    /**
88	     * @param encoding File encoding to write. If null, platform default encoding is chosen.
89	     *
90	     * @deprecated Use {@link #AtomicFileWriter(Path, Charset)}
91	     */
92	    @Deprecated
93	    public AtomicFileWriter(@NonNull File f, @Nullable String encoding) throws IOException {
94	        this(toPath(f), encoding == null ? Charset.defaultCharset() : Charset.forName(encoding));
95	    }
96	
97	    /**
98	     * Wraps potential {@link java.nio.file.InvalidPathException} thrown by {@link File#toPath()} in an
99	     * {@link IOException} for backward compatibility.
100	     *
101	     * @param file file to obtain the path of
102	     * @return the path for that file
103	     * @see File#toPath()
104	     */
105	    private static Path toPath(@NonNull File file) throws IOException {
106	        try {
107	            return file.toPath();
108	        } catch (InvalidPathException e) {
109	            throw new IOException(e);
110	        }
111	    }
112	
113	    /**
114	     * @param destinationPath the destination path where to write the content when committed.
115	     * @param charset File charset to write.
116	     */
117	    public AtomicFileWriter(@NonNull Path destinationPath, @NonNull Charset charset) throws IOException {
118	        // See FileChannelWriter docs to understand why we do not cause a force() call on flush() from AtomicFileWriter.
119	        this(destinationPath, charset, false, true);
120	    }
121	
122	    /**
123	     * <strong>DO NOT USE THIS METHOD, OR YOU WILL LOSE DATA INTEGRITY.</strong>
124	     *
125	     * @param destinationPath the destination path where to write the content when committed.
126	     * @param charset File charset to write.
127	     * @param integrityOnFlush do not force writing to disk when flushing
128	     * @param integrityOnClose do not force writing to disk when closing
129	     * @deprecated use {@link AtomicFileWriter#AtomicFileWriter(Path, Charset)}
130	     */
131	    @Deprecated
132	    public AtomicFileWriter(@NonNull Path destinationPath, @NonNull Charset charset, boolean integrityOnFlush, boolean integrityOnClose) throws IOException {
133	        if (charset == null) { // be extra-defensive if people don't care
134	            throw new IllegalArgumentException("charset is null");
135	        }
136	        this.destPath = destinationPath;
137	        Path dir = this.destPath.getParent();
138	
139	        if (Files.exists(dir) && !Files.isDirectory(dir)) {
140	            throw new IOException(dir + " exists and is neither a directory nor a symlink to a directory");
141	        }
142	        else {
143	            if (Files.isSymbolicLink(dir)) {
144	                LOGGER.log(Level.CONFIG, "{0} is a symlink to a directory", dir);
145	            } else {
146	                Files.createDirectories(dir); // Cannot be called on symlink, so we are pretty defensive...
147	            }
148	        }
149	
150	        try {
151	            // JENKINS-48407: NIO's createTempFile creates file with 0600 permissions, so we use pre-NIO for this...
152	            tmpPath = File.createTempFile("atomic", "tmp", dir.toFile()).toPath();
153	        } catch (IOException e) {
154	            throw new IOException("Failed to create a temporary file in " + dir, e);
155	        }
156	
157	        if (DISABLE_FORCED_FLUSH) {
158	            integrityOnFlush = false;
159	            integrityOnClose = false;
160	        }
161	
162	        core = new FileChannelWriter(tmpPath, charset, integrityOnFlush, integrityOnClose, StandardOpenOption.WRITE, StandardOpenOption.CREATE);
163	
164	        CLEANER.register(this, new CleanupChecker(core, tmpPath, destPath));
165	    }
166	
167	    @Override
168	    public void write(int c) throws IOException {
169	        core.write(c);
170	    }
171	
172	    @Override
173	    public void write(String str, int off, int len) throws IOException {
174	        core.write(str, off, len);
175	    }
176	
