178	    public void write(char[] cbuf, int off, int len) throws IOException {
179	        core.write(cbuf, off, len);
180	    }
181	
182	    @Override
183	    public void flush() throws IOException {
184	        core.flush();
185	    }
186	
187	    @Override
188	    public void close() throws IOException {
189	        core.close();
190	    }
191	
192	    /**
193	     * When the write operation failed, call this method to
194	     * leave the original file intact and remove the temporary file.
195	     * This method can be safely invoked from the "finally" block, even after
196	     * the {@link #commit()} is called, to simplify coding.
197	     */
198	    public void abort() throws IOException {
199	        // One way or another, the temporary file should be deleted.
200	        try {
201	            close();
202	        } finally {
203	            Files.deleteIfExists(tmpPath);
204	        }
205	    }
206	
207	    public void commit() throws IOException {
208	        close();
209	        try {
210	            // Try to make an atomic move.
211	            Files.move(tmpPath, destPath, StandardCopyOption.ATOMIC_MOVE);
212	        } catch (IOException moveFailed) {
213	            // If it falls here that can mean many things. Either that the atomic move is not supported,
214	            // or something wrong happened. Anyway, let's try to be over-diagnosing
215	            if (moveFailed instanceof AtomicMoveNotSupportedException) {
216	                LOGGER.log(Level.WARNING, "Atomic move not supported. falling back to non-atomic move.", moveFailed);
217	            } else {
218	                LOGGER.log(Level.WARNING, "Unable to move atomically, falling back to non-atomic move.", moveFailed);
219	            }
220	
221	            if (destPath.toFile().exists()) {
222	                LOGGER.log(Level.INFO, "The target file {0} was already existing", destPath);
223	            }
224	
225	            try {
226	                Files.move(tmpPath, destPath, StandardCopyOption.REPLACE_EXISTING);
227	            } catch (IOException replaceFailed) {
228	                replaceFailed.addSuppressed(moveFailed);
229	                LOGGER.log(Level.WARNING, "Unable to move {0} to {1}. Attempting to delete {0} and abandoning.",
230	                           new Path[]{tmpPath, destPath});
231	                try {
232	                    Files.deleteIfExists(tmpPath);
233	                } catch (IOException deleteFailed) {
234	                    replaceFailed.addSuppressed(deleteFailed);
235	                    LOGGER.log(Level.WARNING, "Unable to delete {0}, good bye then!", tmpPath);
236	                    throw replaceFailed;
237	                }
238	
239	                throw replaceFailed;
240	            }
241	        }
242	
243	        /*
244	         * From fsync(2) on Linux:
245	         *
246	         *     Calling fsync() does not necessarily ensure that the entry in the directory containing the file has also
247	         *     reached disk. For that an explicit fsync() on a file descriptor for the directory is also needed.
248	         */
249	        if (!DISABLE_FORCED_FLUSH && REQUIRES_DIR_FSYNC) {
250	            try (FileChannel parentChannel = FileChannel.open(destPath.getParent())) {
251	                parentChannel.force(true);
252	            }
253	        }
254	    }
255	
256	    private static final class CleanupChecker implements Runnable {
257	        private final FileChannelWriter core;
258	        private final Path tmpPath;
259	        private final Path destPath;
260	
261	        CleanupChecker(final FileChannelWriter core, final Path tmpPath, final Path destPath) {
262	            this.core = core;
263	            this.tmpPath = tmpPath;
264	            this.destPath = destPath;
265	        }
266	
267	        @Override
268	        public void run() {
269	            if (core.isOpen()) {
270	                LOGGER.log(Level.WARNING, "AtomicFileWriter for " + destPath + " was not closed before being released");
271	                try {
272	                    core.close();
273	                } catch (IOException e) {
274	                    LOGGER.log(Level.WARNING, "Failed to close " + tmpPath + " for destination file " + destPath, e);
275	                }
276	            }
277	            try {
278	                Files.deleteIfExists(tmpPath);
279	            } catch (IOException e) {
280	                LOGGER.log(Level.WARNING, "Failed to delete temporary file " + tmpPath + " for destination file " + destPath, e);
281	            }
282	        }
283	    }
284	
