60	 * <p>
61	 * {@link AdministrativeMonitor}s are bound to URL by {@link Jenkins#getAdministrativeMonitor(String)}.
62	 * See {@link #getUrl()}.
63	 *
64	 * <h3>Views</h3>
65	 * <dl>
66	 * <dt>message.jelly</dt>
67	 * <dd>
68	 * If {@link #isActivated()} returns true, Jenkins will use the {@code message.jelly}
69	 * view of this object to render the warning text. This happens in the
70	 * {@code http://SERVER/jenkins/manage} page. This view should typically render
71	 * a DIV box with class='alert alert-danger' or class='alert alert-warning' with a human-readable text
72	 * inside it. It often also contains a link to a page that provides more details
73	 * about the problem.<br>
74	 * Additionally 2 numbers are shown in the Jenkins header of administrators, one with the number or active
75	 * non-security relevant monitors and one with the number of active security relevant monitors.
76	 * </dd>
77	 * </dl>
78	 *
79	 * <h3>Use with System Read permission</h3>
80	 * <p>
81	 *     By default administrative monitors are visible only to users with Administer permission.
82	 *     Users with {@link Jenkins#SYSTEM_READ} permission can access administrative monitors that override {@link #getRequiredPermission()}.
83	 *     Care needs to be taken to ensure users with that permission don't have access to actions modifying system state.
84	 *     For more details, see {@link #getRequiredPermission()}.
85	 * </p>
86	 *
87	 * @author Kohsuke Kawaguchi
88	 * @since 1.273
89	 * @see Jenkins#administrativeMonitors
90	 */
91	@LegacyInstancesAreScopedToHudson
92	public abstract class AdministrativeMonitor extends AbstractModelObject implements ExtensionPoint, StaplerProxy {
93	    /**
94	     * Human-readable ID of this monitor, which needs to be unique within the system.
95	     *
96	     * <p>
97	     * This ID is used to remember persisted setting for this monitor,
98	     * so the ID should remain consistent beyond the Hudson JVM lifespan.
99	     */
100	    public final String id;
101	
102	    protected AdministrativeMonitor(String id) {
103	        this.id = id;
104	    }
105	
106	    protected AdministrativeMonitor() {
107	        this.id = this.getClass().getName();
108	    }
109	
110	    /**
111	     * Returns the URL of this monitor, relative to the context path, like "administrativeMonitor/foobar".
112	     */
113	    public String getUrl() {
114	        return "administrativeMonitor/" + id;
115	    }
116	
117	    @Override
118	    public String getDisplayName() {
119	        return id;
120	    }
121	
122	    @Override
123	    public final String getSearchUrl() {
124	        return getUrl();
125	    }
126	
127	    /**
128	     * Mark this monitor as disabled, to prevent this from showing up in the UI.
129	     */
130	    public void disable(boolean value) throws IOException {
131	        AbstractCIBase jenkins = Jenkins.get();
132	        Set<String> set = jenkins.getDisabledAdministrativeMonitors();
133	        if (value) {
134	            set.add(id);
135	        } else {
136	            set.remove(id);
137	        }
138	        jenkins.setDisabledAdministrativeMonitors(set);
139	        jenkins.save();
140	    }
141	
142	    /**
143	     * Returns true if this monitor {@link #disable(boolean) isn't disabled} earlier.
