175	     * URL binding to disable this monitor.
176	     */
177	    @RequirePOST
178	    public void doDisable(StaplerRequest req, StaplerResponse rsp) throws IOException {
179	        Jenkins.get().checkPermission(Jenkins.ADMINISTER);
180	        disable(true);
181	        rsp.sendRedirect2(req.getContextPath() + "/manage");
