212	    }
213	
214	    /**
215	     * All registered {@link AdministrativeMonitor} instances.
216	     */
217	    public static ExtensionList<AdministrativeMonitor> all() {
218	        return ExtensionList.lookup(AdministrativeMonitor.class);
219	    }
220	}

