25	package jenkins.model.experimentalflags;
26	
27	import edu.umd.cs.findbugs.annotations.CheckForNull;
28	import edu.umd.cs.findbugs.annotations.NonNull;
29	import edu.umd.cs.findbugs.annotations.Nullable;
30	import hudson.ExtensionList;
31	import hudson.ExtensionPoint;
32	import hudson.model.User;
33	
34	/**
35	 * User specific experimental flag to enable or disable specific behavior.
36	 * As it's user specific, usually this kind of feature flag is only used for UI.
37	 *
38	 * @since 2.395
39	 */
40	public abstract class UserExperimentalFlag<T> implements ExtensionPoint {
41	    private final String flagKey;
42	
43	    protected UserExperimentalFlag(@NonNull String flagKey) {
44	        this.flagKey = flagKey;
45	    }
46	
47	    public abstract @NonNull T getDefaultValue();
48	
49	    /**
50	     * Convert the usable value into a serializable form that can be stored in the user property.
51	     * If no changes are necessary, simply returning the {@code rawValue} is fine.
52	     */
53	    public abstract @Nullable Object serializeValue(T rawValue);
54	
55	    /**
56	     * Convert the serialized value into the usable instance.
57	     * If the instance is invalid (like after migration),
58	     * returning {@code null} will force to return the {@link #getDefaultValue()}
59	     */
60	    protected abstract @Nullable T deserializeValue(Object serializedValue);
61	
62	    /**
63	     * The name that will be used in the configuration page for that flag
64	     * It must be user readable
65	     */
66	    public abstract String getDisplayName();
67	
68	    /**
69	     * Describe what the flag is changing depending on its value.
70	     * This method is called in description.jelly, which could be overloaded by children.
71	     * It could return HTML content.
72	     */
73	    public abstract @Nullable String getShortDescription();
74	
75	    /**
76	     * The ID used by the machine to link the flag with its value within the user properties
77	     */
78	    public @NonNull String getFlagKey() {
79	        return flagKey;
80	    }
81	
82	    public @NonNull T getFlagValue() {
83	        User currentUser = User.current();
84	        if (currentUser == null) {
85	            // the anonymous user is not expected to use flags
86	            return this.getDefaultValue();
87	        }
88	        return this.getFlagValue(currentUser);
89	    }
90	
91	    public @NonNull T getFlagValue(User user) {
92	        UserExperimentalFlagsProperty property = user.getProperty(UserExperimentalFlagsProperty.class);
93	        if (property == null) {
94	            // if for whatever reason there is no such property
95	            return this.getDefaultValue();
96	        }
97	
98	        Object value = property.getFlagValue(this.flagKey);
99	        if (value == null) {
100	            return this.getDefaultValue();
101	        }
102	
103	        T convertedValue = this.deserializeValue(value);
104	        if (convertedValue == null) {
105	            return this.getDefaultValue();
106	        }
107	        return convertedValue;
108	    }
109	
110	    public String getFlagDescriptionPage() {
111	        return "flagDescription.jelly";
112	    }
113	
114	    public String getFlagConfigPage() {
115	        return "flagConfig.jelly";
116	    }
117	
118	    @NonNull
119	    @SuppressWarnings("rawtypes")
120	    public static ExtensionList<UserExperimentalFlag> all() {
121	        return ExtensionList.lookup(UserExperimentalFlag.class);
122	    }
123	
124	    /**
125	     * From the flag class, return the value of the flag for the current user
126	     * If the returned value is {@code null},
127	     * it means that either the class was not found or the current user is anonymous
128	     */
129	    @SuppressWarnings("unchecked")
130	    public static @CheckForNull <T> T getFlagValueForCurrentUser(String flagClassCanonicalName) {
131	        Class<? extends UserExperimentalFlag<T>> flagClass;
132	        try {
133	            Class<?> clazz = Thread.currentThread().getContextClassLoader().loadClass(flagClassCanonicalName);
134	            if (!UserExperimentalFlag.class.isAssignableFrom(clazz)) {
135	                return null;
136	            }
137	            flagClass = (Class<? extends UserExperimentalFlag<T>>) clazz;
138	        } catch (Exception e) {
139	            return null;
140	        }
141	
142	        UserExperimentalFlag<T> userExperimentalFlag = all().get(flagClass);
143	        if (userExperimentalFlag == null) {
144	            return null;
145	        }
146	
147	        return userExperimentalFlag.getFlagValue();
148	    }
149	}

