29	/**
30	 * @since 2.395
31	 */
32	public abstract class BooleanUserExperimentalFlag extends UserExperimentalFlag<Boolean> {
33	    protected BooleanUserExperimentalFlag(@NonNull String flagKey) {
34	        super(flagKey);
35	    }
36	
37	    @Override
38	    public @NonNull Boolean getDefaultValue() {
39	        return false;
40	    }
41	
42	    @Override
43	    public Object serializeValue(Boolean rawValue) {
44	        if (rawValue == null) {
45	            return null;
46	        }
47	        return rawValue ? "true" : "false";
48	    }
49	
50	    @Override
51	    protected Boolean deserializeValue(Object serializedValue) {
