42	/**
43	 * Per user experimental flags to enable features that still not completely ready to be active by default.
44	 *
45	 * @since 2.395
46	 */
47	public class UserExperimentalFlagsProperty extends UserProperty {
48	    private Map<String, String> flags = new HashMap<>();
49	
50	    @DataBoundConstructor
51	    public UserExperimentalFlagsProperty() {
52	    }
53	
54	    public UserExperimentalFlagsProperty(Map<String, String> flags) {
55	        this.flags = new HashMap<>(flags);
56	    }
57	
58	    public @CheckForNull Object getFlagValue(String flagKey) {
59	        return this.flags.get(flagKey);
60	    }
61	
62	    @Extension(ordinal = -500)
63	    @Symbol("experimentalFlags")
64	    public static final class DescriptorImpl extends UserPropertyDescriptor {
65	        @Override
66	        public @NonNull String getDisplayName() {
67	            return Messages.UserExperimentalFlagsProperty_DisplayName();
68	        }
69	
70	        @Override
71	        public @NonNull UserProperty newInstance(User user) {
72	            return new UserExperimentalFlagsProperty();
73	        }
74	
75	        @Override
76	        public UserProperty newInstance(@Nullable StaplerRequest req, @NonNull JSONObject formData) throws FormException {
77	            JSONObject flagsObj = formData.getJSONObject("flags");
78	            Map<String, String> flags = new HashMap<>();
79	            for (Object key : flagsObj.keySet()) {
80	                String value = (String) flagsObj.get((String) key);
81	                if (!value.isEmpty()) {
82	                    flags.put((String) key, value);
83	                }
84	            }
85	            return new UserExperimentalFlagsProperty(flags);
86	        }
87	    }
88	}

